-- Вставка моделей BMW
INSERT INTO models (id, model_id, name, brand, image, description, sort_order, is_active) VALUES
('E81', 'E81', 'BMW E81', 'BMW', 'https://images.pexels.com/photos/170811/pexels-photo-170811.jpeg', 'BMW E81 - трехдверный хэтчбек первой серии, выпускавшийся с 2004 по 2011 год. Этот компактный автомобиль стал первым заднеприводным хэтчбеком в премиум-сегменте. Оснащался бензиновыми двигателями объемом от 1.6 до 3.0 литра и дизельными моторами от 2.0 литра. Модель отличалась спортивной управляемостью благодаря классической компоновке с задним приводом и идеальному распределению веса 50:50. Интерьер выполнен в типичном для BMW стиле с ориентацией на водителя. Автомобиль получил высокие оценки за динамику и удовольствие от вождения. Часто встречающиеся проблемы: растяжение цепи ГРМ на двигателях N47, течи масла, износ задних сайлентблоков. Наш сервис специализируется на обслуживании E81 и поможет поддерживать ваш автомобиль в идеальном состоянии.', 1, true),
('E82', 'E82', 'BMW E82', 'BMW', 'https://images.pexels.com/photos/244206/pexels-photo-244206.jpeg', 'BMW E82 - двухдверное купе первой серии, производившееся с 2007 по 2013 год. Модель представляет собой спортивную версию компактного BMW с более жестким кузовом и агрессивным дизайном. Линейка двигателей включала бензиновые агрегаты от 2.0 до 3.0 литра, включая мощный 135i с твин-турбо мотором N54/N55 мощностью до 306 л.с. Также выпускалась эксклюзивная версия 1M Coupe с 340-сильным двигателем. Автомобиль высоко ценится энтузиастами за отличную управляемость и компактные размеры. Типичные проблемы: неисправности турбин на N54, течи из прокладок, износ подвески при агрессивной езде. Мы выполняем полный спектр работ по обслуживанию и ремонту BMW E82.', 2, true),
('E87', 'E87', 'BMW E87', 'BMW', 'https://images.pexels.com/photos/time-lapse-photography-of-blue-lights-193999.jpeg', 'BMW E87 - пятидверный хэтчбек первой серии, выпускавшийся с 2004 по 2011 год. Это первый компактный автомобиль BMW с задним приводом, ставший эталоном в классе премиальных хэтчбеков. Доступны бензиновые двигатели от 116i до 130i и экономичные дизели. Модель сочетает практичность пятидверного кузова с фирменной динамикой BMW. Просторный для своего класса салон и качественные материалы отделки. Рестайлинг 2007 года принес обновленный дизайн и улучшенные двигатели. Характерные проблемы: вибрации на холостых, износ цепи ГРМ, течи антифриза. В нашем сервисе есть все необходимое оборудование для диагностики и ремонта E87.', 3, true)
ON CONFLICT (id) DO UPDATE SET
  model_id = EXCLUDED.model_id,
  name = EXCLUDED.name,
  brand = EXCLUDED.brand,
  image = EXCLUDED.image,
  description = EXCLUDED.description,
  sort_order = EXCLUDED.sort_order,
